import 'package:flutter/material.dart';
class ConfirmationDialog extends StatelessWidget { const ConfirmationDialog({required this.title, required this.message, required this.onConfirm, this.confirmLabel = 'Confirm', super.key}); final String title; final String message; final VoidCallback onConfirm; final String confirmLabel; @override Widget build(BuildContext context) => AlertDialog(title: Text(title), content: Text(message), actions: [TextButton(onPressed: () => Navigator.pop(context), child: const Text('Cancel')), FilledButton(onPressed: () { onConfirm(); Navigator.pop(context); }, child: Text(confirmLabel))]); }
